(function () {
    let STDoc = document;
    if (window.parent && window.parent.document && window.parent.document !== document) {
        STDoc = window.parent.document;
    }

    const SCRIPT_INSTANCE_KEY = "__sl_header_adjuster_v53_linkage_initialized__";
    const scriptHost = STDoc.defaultView || window;
    if (scriptHost[SCRIPT_INSTANCE_KEY]) return;
    scriptHost[SCRIPT_INSTANCE_KEY] = true;

    let isUpdating = false;
    let syncTimer = null;
    let syncPending = false;
    let lastActiveKeyword = null;

    // ==========================================
    // 源代码借用@电波系-日月西
    // ==========================================
    const SCRIPT_NAME = "SL";
    const COT_TAG = {
        name: "SL",
        prefix: "<star_cot>",
        suffix: "</star_cot>",
        separator: ""
    };

    // 排除主体参数模板（Flash 专属）
    const EXCLUDE_PARAMS_BODY = [
        'presence_penalty',
        'frequency_penalty',
        'top_p',
        'top_k',
        'temperature'
    ].map(e => `- ${e}`).join('\n');

    // 模型 4 选 1 配置矩阵与参数
    const MODEL_CONFIG = [
        { keyword: "GEMINI-F", temp: 1.0, freq: 0, pres: 0, topP: 0.9, type: "F", startReplyWith: "" },
        { keyword: "GEMINI-P",   temp: 1.5, freq: 0.1, pres: 0, topP: 0.88, type: "NORMAL", startReplyWith: "" },
        { keyword: "CLAUDE",   temp: 1.4, freq: 0,   pres: 0, topP: 0.90, type: "NORMAL", startReplyWith: "" },
        { keyword: "GLM",      temp: 1.0, freq: 0,   pres: 0, topP: 0.90, type: "NORMAL", startReplyWith: "" }
    ];

    const COT_F_KEY = "Skip COT-F";
    const COT_NORMAL_KEY = "Skip COT";
    const F_BOTTOM_KEY = "📌☆底部";
    const TOP_STATEMENT_1_KEY = "Top statement1";
    const TOP_STATEMENT_2_KEY = "Top statement2";

    function isArgon4AApiModel(model) {
        return /(?:^|[^a-z0-9])gemini?-4-argon(?=$|[^a-z0-9])/i.test(String(model || ""));
    }

    // 辅助匹配函数
    function getModelConfig(name) {
        if (!name) return null;
        if (name.includes("GEMINI-F")) return MODEL_CONFIG.find(c => c.keyword === "GEMINI-F");
        if (name.includes("GEMINI-P")) return MODEL_CONFIG.find(c => c.keyword === "GEMINI-P");
        if (name.includes("CLAUDE"))   return MODEL_CONFIG.find(c => c.keyword === "CLAUDE");
        if (name.includes("GLM"))      return MODEL_CONFIG.find(c => c.keyword === "GLM");
        return null;
    }

    // 读取 API 连接页当前选中的模型
    function getActiveApiModel() {
        if (SillyTavern.mainApi !== 'openai') return '';
        try {
            const model = SillyTavern.getChatCompletionModel?.();
            if (typeof model === 'string') return model.trim();
        } catch (e) {}
        const settings = SillyTavern.chatCompletionSettings;
        if (!settings) return '';
        const modelFields = {
            custom: 'custom_model', openai: 'openai_model', makersuite: 'google_model',
            openrouter: 'openrouter_model', claude: 'claude_model',
            ai21: 'ai21_model', mistralai: 'mistralai_model', cohere: 'cohere_model',
            deepseek: 'deepseek_model', groq: 'groq_model', xai: 'xai_model'
        };
        const field = modelFields[settings.chat_completion_source];
        return field ? String(settings[field] || '').trim() : '';
    }

    function isFlashApiModel(model) {
        return /(?:^|[^a-z0-9])flash(?:[^a-z0-9]|$)/i.test(model);
    }

    function getApiSamplingConfig(model) {
        if (isFlashApiModel(model)) return MODEL_CONFIG.find(config => config.type === 'F');
        const isGeminiPro = /gemini/i.test(model) && /(?:^|[^a-z0-9])(?:pro|p)(?:[^a-z0-9]|$)/i.test(model);
        return isGeminiPro ? MODEL_CONFIG.find(config => config.keyword === 'GEMINI-P') : null;
    }

    function getApiPromptConfig(model) {
        const samplingConfig = getApiSamplingConfig(model);
        if (samplingConfig) return samplingConfig;
        // 4A 与 Flash 共用提示词条目，但不自动填写 4A 的采样参数。
        if (isArgon4AApiModel(model)) {
            return MODEL_CONFIG.find(config => config.type === 'F');
        }
        return null;
    }

    // ==========================================
    // 🛠️ 1. 自动配置排除主体参数 (Flash 专属)
    // ==========================================
    async function syncCustomExcludeBody(isFlashModel) {
        try {
            const settings = SillyTavern.chatCompletionSettings;
            if (!settings) return;

            const isCustomOpenAI = (SillyTavern.mainApi === 'openai' && settings.chat_completion_source === 'custom');
            const existingExcludeBody = String(settings.custom_exclude_body || '');
            const targetExcludeBody = (isCustomOpenAI && isFlashModel)
                ? EXCLUDE_PARAMS_BODY
                : (existingExcludeBody === EXCLUDE_PARAMS_BODY ? '' : existingExcludeBody);

            if (String(settings.custom_exclude_body || '') !== targetExcludeBody) {
                settings.custom_exclude_body = targetExcludeBody;
                $('#custom_exclude_body', STDoc).val(targetExcludeBody);
                if (typeof SillyTavern.saveSettingsDebounced === 'function') {
                    await SillyTavern.saveSettingsDebounced();
                }
                console.info(`[${SCRIPT_NAME} 助手] ${targetExcludeBody ? '已自动填写 Flash 排除参数' : '已清空排除参数'}`);
            }
        } catch (e) {
            console.warn(`[${SCRIPT_NAME} 助手] 配置排除参数失败:`, e);
        }
    }

    function setCheckbox(selector, val) {
        const el = $(selector, STDoc);
        if (el.length && el.prop('checked') !== val) {
            el.prop('checked', val).trigger('change');
        }
    }

    async function autoConfigureReasoning() {
        try {
            const reasoningSelect = $('#reasoning_select', STDoc);
            const presetManager = SillyTavern.getPresetManager?.('reasoning');
            if (!reasoningSelect.length || !presetManager) return;

            const allPresets = presetManager.getAllPresets?.() || [];
            const currentPreset = allPresets.includes(COT_TAG.name)
                ? presetManager.getCompletionPresetByName?.(COT_TAG.name)
                : null;

            if (currentPreset?.prefix === COT_TAG.prefix && currentPreset?.suffix === COT_TAG.suffix) {
                if (reasoningSelect.val() !== COT_TAG.name) {
                    reasoningSelect.val(COT_TAG.name).trigger('change');
                }
            } else {
                await presetManager.savePreset(COT_TAG.name, COT_TAG);
                reasoningSelect.val(COT_TAG.name).trigger('change');
            }

            // 自动勾选解析
            setCheckbox('#reasoning_auto_parse', true);
            setCheckbox('#reasoning_auto_expand', false);
            setCheckbox('#reasoning_show_hidden', true);
            setCheckbox('#reasoning_add_to_prompts', false);

            const maxAdditions = $('#reasoning_max_additions', STDoc);
            if (maxAdditions.length && String(maxAdditions.val() ?? '') !== '1') {
                maxAdditions.val('1').trigger('input');
            }
        } catch (e) {
            console.warn(`[${SCRIPT_NAME} 助手] 自动配置推理格式化跳过:`, e);
        }
    }

    function setStartReplyWith(text) {
        if (typeof text === 'undefined') return;
        const input = $('#start_reply_with', STDoc);
        if (input.length && String(input.val() ?? '') !== text) {
            input.val(text).trigger('input');
        }
        const showReplyPrefix = $('#chat-show-reply-prefix-checkbox', STDoc);
        if (showReplyPrefix.length && !showReplyPrefix.prop('checked')) {
            showReplyPrefix.prop('checked', true).trigger('change');
        }
    }

    // ==========================================
    // 🛠️ 4. 滑动条与参数派发
    // ==========================================
    function changeSliders(temp, freq, pres, topP) {
        const setVal = (baseId, val) => {
            if (typeof $ === 'undefined') return;
            $(`input[type="range"][id^="${baseId}_"]`, STDoc).each(function() {
                $(this).val(val).trigger('input').trigger('change');
            });
            $(`input[type="number"][id^="${baseId}_counter_"]`, STDoc).each(function() {
                $(this).val(val).trigger('input');
            });
        };

        setVal('temp', temp);
        setVal('freq_pen', freq);
        setVal('pres_pen', pres);
        setVal('top_p', topP);

        if (typeof $ !== 'undefined') {
            $('#update_oai_preset', STDoc).trigger('click');
        }
    }

    function getExpectedEnabled(prompt, targetModel, wantCotF, wantCotNormal, wantFBottom, isArgon4A) {
        if (prompt.name.includes(TOP_STATEMENT_1_KEY)) return !isArgon4A;
        if (prompt.name.includes(TOP_STATEMENT_2_KEY)) return isArgon4A;
        if (getModelConfig(prompt.name)) return prompt.name === targetModel;
        if (prompt.name.includes(COT_F_KEY)) return wantCotF;
        if (prompt.name.includes(COT_NORMAL_KEY) && !prompt.name.includes(COT_F_KEY)) return wantCotNormal;
        if (prompt.name.includes(F_BOTTOM_KEY)) return wantFBottom;
        return null;
    }

    function presetNeedsSync(preset, targetModel, wantCotF, wantCotNormal, wantFBottom, isArgon4A) {
        return !!preset?.prompts?.some(prompt => {
            const expected = getExpectedEnabled(prompt, targetModel, wantCotF, wantCotNormal, wantFBottom, isArgon4A);
            return expected !== null && prompt.enabled !== expected;
        });
    }

    function scheduleSyncModels(delay = 200) {
        if (syncTimer !== null) clearTimeout(syncTimer);
        syncTimer = setTimeout(() => {
            syncTimer = null;
            void syncModels();
        }, delay);
    }

    async function syncModels(forcedTargetModelName = null) {
        if (isUpdating) {
            syncPending = true;
            return;
        }

        try {
            const currentPreset = getPreset('in_use');
            if (!currentPreset || !currentPreset.prompts) return;

            // API 模型决定预设条目和头部状态
            const apiModel = getActiveApiModel();
            const isArgon4A = isArgon4AApiModel(apiModel);
            const apiPromptConfig = getApiPromptConfig(apiModel);
            let targetModel = forcedTargetModelName;

            if (!targetModel && apiPromptConfig) {
                const apiPrompt = currentPreset.prompts.find(prompt =>
                    getModelConfig(prompt.name)?.keyword === apiPromptConfig.keyword
                );
                targetModel = apiPrompt?.name || null;
            }

            if (!targetModel) {
                const activeList = currentPreset.prompts.filter(p => p.enabled && getModelConfig(p.name));
                if (activeList.length > 0) targetModel = activeList[0].name;
            }

            const targetConf = targetModel ? getModelConfig(targetModel) : null;
            const isFlash = targetConf ? targetConf.type === "F" : false;

            // 状态分配
            const wantCotF = isFlash;
            const wantCotNormal = targetConf ? targetConf.type === "NORMAL" : false;
            const wantFBottom = isFlash;

            // 执行强制锁定与预设写回
            isUpdating = true;
            const enforce = (preset) => {
                if (!preset || !preset.prompts) return preset;
                preset.prompts.forEach(prompt => {
                    const expected = getExpectedEnabled(prompt, targetModel, wantCotF, wantCotNormal, wantFBottom, isArgon4A);
                    if (expected !== null) prompt.enabled = expected;
                });
                return preset;
            };

            if (presetNeedsSync(currentPreset, targetModel, wantCotF, wantCotNormal, wantFBottom, isArgon4A)) {
                await updatePresetWith('in_use', enforce, { render: 'immediate' });
            }

            const currentPresetName = getLoadedPresetName();
            if (currentPresetName) {
                const namedPreset = getPreset(currentPresetName);
                if (!namedPreset || presetNeedsSync(namedPreset, targetModel, wantCotF, wantCotNormal, wantFBottom, isArgon4A)) {
                    await updatePresetWith(currentPresetName, enforce);
                }
            }

            // 回复前缀按条目联动；采样参数由 API 的 Flash / Gemini Pro 模型触发。
            if (targetConf) setStartReplyWith(targetConf.startReplyWith);

            const apiIsFlash = isFlashApiModel(apiModel);
            await syncCustomExcludeBody(apiIsFlash);
            const apiConf = getApiSamplingConfig(apiModel);

            if (apiConf) {
                const apiKey = `${SillyTavern.chatCompletionSettings?.chat_completion_source || ''}:${apiModel}`;
                if (lastActiveKeyword !== apiKey) {
                    lastActiveKeyword = apiKey;
                    changeSliders(apiConf.temp, apiConf.freq, apiConf.pres, apiConf.topP);
                    if (typeof toastr !== 'undefined') {
                        toastr.success(`✦ [${SCRIPT_NAME}] 已识别 ${apiConf.keyword} API 模型：${apiModel}，自动填写对应参数`);
                    }
                }
            } else {
                // 其他模型或无法识别时，不填写采样参数。
                lastActiveKeyword = null;
            }
        } catch (e) {
            console.error(`[${SCRIPT_NAME}] 同步失败:`, e);
        } finally {
            isUpdating = false;
            if (syncPending) {
                syncPending = false;
                scheduleSyncModels(200);
            }
        }
    }

    $(() => {
        // 初始延迟初始化
        setTimeout(async () => {
            await autoConfigureReasoning();
            await syncModels();
        }, 1200);

        // 监听酒馆 UI 点击
        $(STDoc).on('click', '.range-block, .checkbox_label, input[type="checkbox"], .prompt-manager-toggle-action, #completion_prompt_manager', function () {
            scheduleSyncModels(150);
        });

        // 监听自定义 API 模型输入框
        $(STDoc).on('input change', '#custom_model_id, #model_custom_select', function () {
            scheduleSyncModels(400);
        });

        // 监听 API 来源、模型和系统设置变化
        if (typeof tavern_events !== 'undefined') {
            if (tavern_events.CHATCOMPLETION_SOURCE_CHANGED) {
                eventOn(tavern_events.CHATCOMPLETION_SOURCE_CHANGED, () => scheduleSyncModels(200));
            }
            if (tavern_events.CHATCOMPLETION_MODEL_CHANGED) {
                eventOn(tavern_events.CHATCOMPLETION_MODEL_CHANGED, () => scheduleSyncModels(200));
            }
            if (tavern_events.SETTINGS_UPDATED) {
                eventOn(tavern_events.SETTINGS_UPDATED, () => scheduleSyncModels(200));
            }
            if (tavern_events.PRESET_CHANGED) {
                eventOn(tavern_events.PRESET_CHANGED, async () => {
                    lastActiveKeyword = null;
                    await autoConfigureReasoning();
                    scheduleSyncModels(500);
                });
            }
        }
    });
})();

